    // Create Icon component factory
    function createIcon(name, pathData) {
        function Icon({ size = 24, color = 'currentColor', strokeWidth = 2, className = '', style = {}, ...props }) {
            return React.createElement('svg', {
                xmlns: 'http://www.w3.org/2000/svg',
                width: size,
                height: size,
                viewBox: '0 0 24 24',
                fill: 'none',
                stroke: color,
                strokeWidth: strokeWidth,
                strokeLinecap: 'round',
                strokeLinejoin: 'round',
                className: `lucide lucide-${name} ${className}`,
                style,
                ...props
            }, React.createElement('path', { d: pathData }));
        }
        Icon.displayName = name.split('-').map(s => s.charAt(0).toUpperCase() + s.slice(1)).join('');
        return Icon;
    }

    // Create all icon components
    const LucideIcons = {};
    Object.entries(icons).forEach(([name, pathData]) => {
        const componentName = name.split('-').map(s => s.charAt(0).toUpperCase() + s.slice(1)).join('');
        LucideIcons[componentName] = createIcon(name, pathData);
    });

    // Expose globally
    Object.assign(global, LucideIcons);
    global.LucideIcons = LucideIcons;

